export const NAVIGATION_ORIGIN = Object.freeze({
	APPROVAL_REQUESTS: 'approval-requests',
	APPROVAL_CUTI: 'approval-cuti',
	PENYESUAIAN_CUTI: 'penyesuaian-cuti',
	OPER_PIC: 'oper-pic',
})

const ORIGIN_DESTINATIONS = Object.freeze({
	[NAVIGATION_ORIGIN.APPROVAL_REQUESTS]: Object.freeze({
		target: Object.freeze({ name: 'WorkflowRequests' }),
		label: 'Approval Requests',
	}),
	[NAVIGATION_ORIGIN.APPROVAL_CUTI]: Object.freeze({
		target: Object.freeze({ name: 'CutiApproval' }),
		label: 'Approval Cuti',
	}),
	[NAVIGATION_ORIGIN.PENYESUAIAN_CUTI]: Object.freeze({
		target: Object.freeze({ name: 'PenyesuaianCuti' }),
		label: 'Penyesuaian Cuti',
	}),
	[NAVIGATION_ORIGIN.OPER_PIC]: Object.freeze({
		target: Object.freeze({ name: 'OperPic' }),
		label: 'Oper PIC',
	}),
})

function firstQueryValue(value) {
	return Array.isArray(value) ? value[0] : value
}

export function validNavigationOrigin(value) {
	const origin = String(firstQueryValue(value) || '')
	return Object.prototype.hasOwnProperty.call(ORIGIN_DESTINATIONS, origin) ? origin : null
}

export function withNavigationOrigin(target, origin) {
	const validOrigin = validNavigationOrigin(origin)
	if (!validOrigin) return { ...target }
	return {
		...target,
		query: {
			...(target.query || {}),
			origin: validOrigin,
		},
	}
}

export function resolveBackNavigation(route, fallbackTarget, fallbackLabel = 'Daftar') {
	const origin = validNavigationOrigin(route?.query?.origin)
	const destination = origin ? ORIGIN_DESTINATIONS[origin] : null
	return destination
		? { target: { ...destination.target }, label: destination.label, origin }
		: { target: { ...fallbackTarget }, label: fallbackLabel, origin: null }
}
